      setIsAuthenticatedPortalUser(Boolean(session?.idToken));
    }).catch(() => {
      setIsAuthenticatedPortalUser(false);
    });
  }, []);

  useEffect(() => {
    if (!mounted || !sessionData || sessionData.status !== "authenticated" || !sessionData.data?.user) {
      return;
    }

    const fetchSubscriptionStatus = async () => {
      try {
        const user = sessionData.data!.user as any;
        const userId = user?.sub || user?.email;

        if (!userId) return;

        const res = await fetch(`/api/subscription/${userId}`);
        if (res.ok) {
          const subscription = await res.json();
          setIsMember(subscription.status === "active");
        }
      } catch (error) {
        console.error("Error fetching subscription status:", error);
      }
    };

    fetchSubscriptionStatus();
  }, [sessionData?.status, sessionData?.data, mounted]);

  const toggleChapter = (moduleCode: string, chapterId: string) => {
    if (!isMember) return;

    setModules((prev) =>
      prev.map((mod) => {
        if (mod.code !== moduleCode) return mod;
