def file_metadata(path):
    """Return stable audit metadata for a source or generated artifact."""
    with open(path, "rb") as file_handle:
        digest = hashlib.sha256(file_handle.read()).hexdigest()
    stat_result = os.stat(path)
    return {
        "path": os.path.relpath(path, BASE_DIR),
        "sha256": digest,
        "size_bytes": stat_result.st_size,
        "modified_at": datetime.fromtimestamp(stat_result.st_mtime).isoformat(),
    }


def get_tree_leaf(tree, h1, h2, h3):
    """Direct helper to retrieve the correct leaves to insert text paragraphs into."""
    if h1 not in tree:
        tree[h1] = {"title": h1, "subsections": {}, "paragraphs": []}
    if h2:
        if h2 not in tree[h1]["subsections"]:
            tree[h1]["subsections"][h2] = {"title": h2, "subsections": {}, "paragraphs": []}
        if h3:
            if h3 not in tree[h1]["subsections"][h2]["subsections"]:
                tree[h1]["subsections"][h2]["subsections"][h3] = {"title": h3, "paragraphs": []}
            return tree[h1]["subsections"][h2]["subsections"][h3]["paragraphs"]
        return tree[h1]["subsections"][h2]["paragraphs"]
    return tree[h1]["paragraphs"]


